<html lang="zh-CN">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>海鸥节奏隔离原型</title>
  <style>
    :root { color-scheme: dark; font-family: system-ui, sans-serif; }
    body { margin: 0; background: #071f2b; color: #eaf7f7; }
    main { width: min(680px, 100% - 24px); margin: 18px auto; }
    .notice { border: 1px solid #f1c75b; background: #382f16; padding: 10px; }
    .controls, .status { display:flex; gap:12px; align-items:center; flex-wrap:wrap; margin:12px 0; }
    button { font: inherit; padding: 8px 14px; cursor:pointer; }
    canvas { width: min(100%, 480px); aspect-ratio:3/2; display:block; background:#17617a; border:1px solid #77b7c7; image-rendering:auto; }
    #phase { font-weight:700; color:#ffd766; }
    small { color:#b8d3d8; }
  </style>
</head>
<body>
<main>
  <h1>海鸥预警与拾回节奏</h1>
  <p class="notice">隔离体验通道：约 1 秒预警仍是未决项，不是已采纳设计。本页只供开发者亲自判断是否来得及反应。</p>
  <div class="controls"><button id="start">开始一次俯冲</button><span>方向键移动螃蟹</span></div>
  <div class="status"><span id="phase">待开始</span><span id="timer"></span></div>
  <canvas id="game" width="480" height="320"></canvas>
  <p><small>节奏：预警约 1 秒 → 海鸥俯冲抢走 → 贝壳落在附近 → 3 秒内靠近拾回。每次点击重新开始；这不是正式海鸥系统。</small></p>
</main>
<script>
const canvas = document.querySelector('#game');
const ctx = canvas.getContext('2d');
const phaseEl = document.querySelector('#phase');
const timerEl = document.querySelector('#timer');
const player = {x:240,y:160,speed:120};
const keys = {};
let phase='idle', phaseStart=performance.now(), shell=null, last=performance.now();
addEventListener('keydown', e => { if (e.key.startsWith('Arrow')) { keys[e.key]=true; e.preventDefault(); }});
addEventListener('keyup', e => { keys[e.key]=false; });
document.querySelector('#start').addEventListener('click', () => {
  phase='warning'; phaseStart=performance.now(); shell=null;
});
function dropShell() {
  const a=Math.random()*Math.PI*2, r=70+Math.random()*70;
  shell={x:Math.max(8,Math.min(472,player.x+Math.cos(a)*r)),y:Math.max(8,Math.min(312,player.y+Math.sin(a)*r))};
}
function update(now,dt) {
  const elapsed=(now-phaseStart)/1000;
  if (phase==='warning' && elapsed>=1) { phase='recover'; phaseStart=now; dropShell(); }
  if (phase==='recover' && shell && Math.hypot(shell.x-player.x,shell.y-player.y)<14) { phase='caught'; shell=null; }
  if (phase==='recover' && (now-phaseStart)/1000>=3) { phase='lost'; shell=null; }
  let dx=(keys.ArrowRight?1:0)-(keys.ArrowLeft?1:0), dy=(keys.ArrowDown?1:0)-(keys.ArrowUp?1:0);
  if (dx||dy) { const n=Math.hypot(dx,dy); player.x+=dx/n*player.speed*dt; player.y+=dy/n*player.speed*dt; }
  player.x=Math.max(10,Math.min(470,player.x)); player.y=Math.max(7,Math.min(313,player.y));
  const labels={idle:'待开始',warning:'⚠ 海鸥影子！',recover:'贝壳被抢，快追回！',caught:'已拾回',lost:'拾回超时'};
  phaseEl.textContent=labels[phase];
  timerEl.textContent=phase==='warning'?`预警 ${(1-elapsed).toFixed(1)} 秒`:phase==='recover'?`拾回 ${Math.max(0,3-(now-phaseStart)/1000).toFixed(1)} 秒`:'';
}
function draw(now) {
  ctx.clearRect(0,0,480,320);
  ctx.fillStyle='#d9b35f'; ctx.fillRect(player.x-10,player.y-7,20,14);
  if (phase==='warning') { ctx.strokeStyle='#ffd24a'; ctx.lineWidth=4; ctx.beginPath(); ctx.arc(player.x,player.y,24+6*Math.sin(now/80),0,Math.PI*2); ctx.stroke(); ctx.fillStyle='#fff'; ctx.font='bold 22px sans-serif'; ctx.fillText('!',player.x-3,player.y-30); }
  if (shell) { ctx.fillStyle='#f4eee0'; ctx.beginPath(); ctx.arc(shell.x,shell.y,7,0,Math.PI*2); ctx.fill(); }
}
function frame(now) { const dt=Math.min(.05,(now-last)/1000); last=now; update(now,dt); draw(now); requestAnimationFrame(frame); }
requestAnimationFrame(frame);
</script>
</body>
</html>
